import { Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';

/**
 * Minimal structural view of the generated Prisma client that this app uses.
 *
 * The Prisma client is generated by `prisma generate` and is intentionally NOT a
 * build/test dependency (the in-memory path needs no client). To keep `nest build`
 * and tests working without a generated client on disk, the client is loaded via a
 * guarded dynamic require at runtime and typed structurally here. When DATABASE_URL
 * is unset, this service is never instantiated.
 */
export interface PrismaModelDelegate {
  create(args: { data: unknown }): Promise<unknown>;
  findUnique(args: { where: unknown }): Promise<unknown>;
  findMany(args?: { where?: unknown }): Promise<unknown[]>;
  update(args: { where: unknown; data: unknown }): Promise<unknown>;
  upsert(args: { where: unknown; create: unknown; update: unknown }): Promise<unknown>;
  delete(args: { where: unknown }): Promise<unknown>;
  deleteMany(args?: { where?: unknown }): Promise<{ count: number }>;
}

export interface PrismaClientLike {
  $connect(): Promise<void>;
  $disconnect(): Promise<void>;
  user: PrismaModelDelegate;
  caregiverLink: PrismaModelDelegate;
  progressRecord: PrismaModelDelegate;
}

@Injectable()
export class PrismaService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(PrismaService.name);
  private client: PrismaClientLike;

  constructor() {
    // Loaded dynamically so a missing/ungenerated client does not break tsc or the
    // in-memory path. Only reached when DATABASE_URL is set.
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const mod = require('@prisma/client') as { PrismaClient: new () => PrismaClientLike };
    this.client = new mod.PrismaClient();
  }

  get db(): PrismaClientLike {
    return this.client;
  }

  async onModuleInit(): Promise<void> {
    await this.client.$connect();
    this.logger.log('Connected to PostgreSQL via Prisma.');
  }

  async onModuleDestroy(): Promise<void> {
    await this.client.$disconnect();
  }
}
